sys_script_include.script:
var IntegrationMoviesUtils = Class.create();
IntegrationMoviesUtils.prototype = {
    initialize: function() {},

    getMovieByTitle: function(title) {
    if (!title || title.trim() === '') {
        gs.error('Título inválido ou vazio recebido em getMovieByTitle');
        return null;
    }

    var rm = new sn_ws.RESTMessageV2('OMDb API', 'GetMovieByTitle');
    rm.setStringParameter('title', title);

    var response = rm.execute();
    var body = response.getBody();
    gs.info('Resposta da API OMDb: ' + body);

    if (response.getStatusCode() !== 200) {
        gs.error('Erro na API OMDb: HTTP ' + response.getStatusCode());
        return null;
    }

    var movieData = JSON.parse(body);

    if (!movieData || movieData.Response === 'False') {
        gs.error('Filme não encontrado: ' + title + ' - ' + movieData.Error);
        return null;
    }

    var movie = new GlideRecord('u_moviesdb');
    movie.initialize();

    // Dados básicos
    movie.u_title = movieData.Title;
    movie.u_director = movieData.Director;
    movie.u_rated = movieData.Rated;
    movie.u_runtime = movieData.Runtime;
    movie.u_genre = movieData.Genre;
    movie.u_released = movieData.Released;
    movie.u_country = movieData.Country;
    movie.u_plot = movieData.Plot;
    movie.u_imdbid = movieData.imdbID;

    movie.u_poster = this.formaterPoster(movieData);

    var sysId = movie.insert();

    if (!sysId) {
        gs.error('Erro: não foi possível inserir o filme: ' + movieData.Title);
        return null;
    }

    gs.info('Filme inserido com sys_id: ' + sysId);
    return sysId.toString();
},

    getMovieById: function(id) {
        var rm = new sn_ws.RESTMessageV2('OMDb API', 'GetMovieById');
        rm.setStringParameter('id', id);

        var response = rm.execute();
        var body = response.getBody();
        gs.info('Resposta da API OMDb: ' + body);

        if (response.getStatusCode() !== 200) {
            gs.error('Erro na API OMDb: HTTP ' + response.getStatusCode());
            return null;
        }

        var movieData = JSON.parse(body);

        if (!movieData || movieData.Response === 'False') {
            gs.error('Filme não encontrado: ' + id + ' - ' + movieData.Error);
            return null;
        }

        var movie = new GlideRecord('u_moviesdb');
        movie.initialize();

        // Dados básicos
        movie.u_title = movieData.Title;
        movie.u_director = movieData.Director;
        movie.u_rated = movieData.Rated;
        movie.u_runtime = movieData.Runtime;
        movie.u_genre = movieData.Genre;
        movie.u_released = movieData.Released;
        movie.u_country = movieData.Country;
        movie.u_plot = movieData.Plot;
        movie.u_imdb_id = movieData.imdbID;

        movie.u_poster = this.formaterPoster(movieData);

        var sysId = movie.insert();

        if (!sysId) {
            gs.error('Erro: não foi possível inserir o filme: ' + movieData.Title);
            return null;
        }

        return sysId.toString();
    },

    formaterPoster: function(movieData) {
        var posterUrl = movieData.Poster || '';
        var ratingsHtml = '';
        var awardsHtml = '';

        if (Array.isArray(movieData.Ratings)) {
            ratingsHtml = '<div style="font-size:20px; line-height:1.6;">';
            for (var i = 0; i < movieData.Ratings.length; i++) {
                var rating = movieData.Ratings[i];
                if (rating.Source && rating.Value) {
                    ratingsHtml += '<div><strong>' + rating.Source + ':</strong> ' + rating.Value + '</div>';
                }
            }
            ratingsHtml += '</div>';
        }

        if (movieData.Awards && movieData.Awards !== '') {
            awardsHtml = '<div style="font-size:20px; line-height:1.6; margin-top:8px; font-style: italic; color: #444;">' +
                movieData.Awards +
                '</div>';
        }

        var combinedHtml =
            '<div style="display:flex; align-items:flex-start; gap:16px; padding:6px;">' +
            (posterUrl ?
                '<img src="' + posterUrl + '" style="height:500px; border-radius:6px; box-shadow:0 2px 8px rgba(0,0,0,0.3); object-fit:contain;" />' :
                '') +
            '<div>' + ratingsHtml + awardsHtml + '</div>' +
            '</div>';

        return combinedHtml;
    },


    type: 'IntegrationMoviesUtils'
};
